const edition = globalThis.makeSubjectEdition({"year":2015,"grade":"7-8","tasksFile":"ZR_1415_7-8.pdf","answersFile":"reviewed-7-8.pdf","title":"Эпоха Возрождения","subject":"golden-fleece","contest":"Золотое руно","letters":"ABCD","count":60,"language":"ru","points":3,"sourceFile":"sources/golden-fleece/2015/7-8.json","sections":[{"start":1,"title":"Общие сведения"},{"start":16,"title":"Идеи"},{"start":31,"title":"Чувства"},{"start":46,"title":"Образы"}],"reviewedKey":true}, [{"title":"Заговор во Флоренции","question":"Заговор Пацци во Флоренции в 1478 году имел целью …","choices":["свержение Медичи","сдачу города Милану","подчинение города Сиксту IV","передачу власти народу"],"answer":0,"steps":["Семейство Пацци и союзники попытались убить Лоренцо и Джулиано Медичи во время службы.","Джулиано погиб, а Лоренцо спасся и сохранил власть."]},{"title":"Карта для глобуса","question":"Первые карты для глобуса, на котором была изображена Северная и Южная Америка, создал …","choices":["Х. Колумб","Генрих Мореплаватель","Ф. Магеллан","М. Вальдзеемюллер"],"answer":3,"steps":["Мартин Вальдземюллер в 1507 году издал карту мира и листы для сборного глобуса.","Он отделил земли за Атлантикой от Азии и употребил название «Америка»."]},{"title":"Папская булла","question":"Что сделал Мартин Лютер в декабре 1520 года в ответ на папскую буллу с угрозой отлучения?","choices":["Публично сжёг папскую буллу","Доказал недействительность индульгенций","Публично отрёкся от своих трудов","Принял монашеский обет"],"answer":0,"steps":["Папа Лев X потребовал, чтобы Лютер отрёкся от ряда своих положений. В ответ Лютер публично сжёг буллу в Виттенберге.","Окончательное отлучение последовало в январе 1521 года."],"references":["https://guides.loc.gov/martin-luther-priest-heretic-outlaw/luther-the-heretic","https://museeprotestant.org/en/notice/martin-luther-1483-1546/"],"taskUrl":"https://runodog.ru/ZR_1415/ZR_1415_7-8.pdf#page=1","adaptation":"Редакция вопроса проверена по первоисточникам."},{"title":"Здание галереи","question":"Дж. Вазари является одним из архитекторов здания этой картинной галереи.","choices":["Галерея Уффици","Капелла Медичи","Палаццо Питти","Национальный музей Барджелло"],"answer":0,"steps":["Вазари спроектировал Уффици как здание флорентийских государственных учреждений.","Позднее в его галереях разместились коллекции Медичи."],"figure":{"src":"assets/golden-fleece/2015/lessons/7-8/4.webp","alt":"Портрет мужчины с бородой и в тёмном берете","width":131,"height":169}},{"title":"Битва Сервантеса","question":"М. Сервантес участвовал в битве при …","choices":["Лепанто","Мариньяно","Павии","Равенне"],"answer":0,"steps":["В 1571 году Сервантес участвовал в морской битве христианской коалиции с османским флотом при Лепанто.","Полученная там рана лишила его возможности пользоваться левой рукой."]},{"title":"Город Реформации","question":"Этот город, благодаря деятельности Ж. Кальвина, превратился в один из важнейших центров Реформации.","choices":["Цюрих","Базель","Женева","Люцерн"],"answer":2,"steps":["Кальвин жил и проповедовал в Женеве.","Её академия готовила протестантских проповедников, которые распространяли реформатские идеи в других странах."]},{"title":"Обсерватория Браге","question":"Одна из созданных Т. Браге в конце XVI века обсерваторий называлась …","choices":["«Звездный замок»","«Круглая башня»","«Дом мудрости»","«Башня Белем»"],"answer":0,"steps":["На острове Вен у Тихо Браге были две обсерватории.","Название Стьернеборг переводится как «Звёздный замок», а Ураниборг назван в честь музы астрономии."]},{"title":"Герой поэмы Камоэнса","question":"Этому мореплавателю посвящено одно из произведений Л. Камоэнса.","choices":["Ф. Магеллан","В. да Гама","Х. Колумб","А. Веспуччи"],"answer":1,"steps":["В «Лузиадах» Камоэнс описал плавание Васко да Гамы вокруг Африки в Индию.","Поэт соединил рассказ о путешествии с мифологическими эпизодами."]},{"title":"Проверка грамоты","question":"«Константинов дар» в XV веке разоблачил …","choices":["М. Фичино","Л. Валла","Л. Б. Альберти","П. Браччолини"],"answer":1,"steps":["Лоренцо Валла обнаружил в грамоте слова и обороты, появившиеся после императора Константина.","По этим признакам он показал, что документ составили позднее."]},{"title":"Возвращение поэмы","question":"Поэму Тита Лукреция Кара «О природе вещей» обнаружил …","choices":["Ф. Петрарка","П. Браччолини","Н. Никколи","Л. Валла"],"answer":1,"steps":["В 1417 году гуманист Поджо Браччолини нашёл список «О природе вещей» в монастырской библиотеке.","Списки поэмы вновь начали распространяться среди учёных."]},{"title":"Мэр города Бордо","question":"Этот французский гуманист исполнял обязанности мэра города Бордо.","choices":["Ж. Лефевр","Э. де ла Боэси","М. Монтень","Ф. Рабле"],"answer":2,"steps":["Мишеля де Монтеня дважды избирали мэром Бордо.","В «Опытах» он описывал не только чтение древних авторов, но и собственный опыт общественной жизни."]},{"title":"Флорентийские законы","question":"Этот закон был принят во Флоренции в конце XIII века.","choices":["«Великая хартия вольностей»","«Зеленая книга»","«Установления справедливости»","«Февральский патент»"],"answer":2,"steps":["«Установления справедливости» 1293 года ограничили доступ знатных семейств к управлению Флоренцией.","Политическая роль горожан, объединённых в цехи, выросла."]},{"title":"Свидетель при дворе","question":"Ф. де Коммин прославился своими …","choices":["поэмами","мемуарами","романами","научными трактатами"],"answer":1,"steps":["Филипп де Коммин служил сначала при бургундском, затем при французском дворе.","В мемуарах он объяснял поступки правителей, многие из которых наблюдал сам."]},{"title":"Итальянец в Москве","question":"Итальянский архитектор П. А. Солари прославился своей работой при дворе этого монарха.","choices":["Иржи Подебрад","Иван III","Казимир IV Ягеллончик","Кристиан I"],"answer":1,"steps":["Пьетро Антонио Солари приехал работать в Москву при Иване III.","С его именем связаны стены и башни Московского Кремля, включая Спасскую."]},{"title":"Земное яблоко","question":"Эта работа мастеров XV века, известная как «Земное яблоко», хранится в Нюрнберге в Германском национальном музее.","choices":["Глобус","Дворец","Орган","Фонтан"],"answer":0,"steps":["Старинный глобус Мартина Бехайма завершили в 1492 году.","На нём ещё нет Америки, поэтому он показывает европейские представления о мире накануне возвращения Колумба."]},{"title":"Учение о вере","question":"«Философией Христа» своё учение назвал …","choices":["М. Лютер","М. Монтень","У. Цвингли","Эразм Роттердамский"],"answer":3,"steps":["Эразм называл «философией Христа» жизнь согласно нравственному смыслу Евангелия.","Он выступал за изучение первоначальных текстов и внутреннее благочестие."]},{"title":"Проект идеального города","question":"Этот художник разработал проект идеального города Ромолонтино.","choices":["Леонардо да Винчи","Рафаэль","Эль Греко","С. Боттичелли"],"answer":0,"steps":["Франциск I пригласил Леонардо во Францию.","С Роморантеном связаны сохранившиеся наброски дворца и проекта преобразования местности с каналами."]},{"title":"Сатира о великанах","question":"Среди главных героев сатирического произведения этого автора были добродушные короли-великаны, живущие в полном несправедливости мире.","choices":["Т. Мор","Ф. Рабле","У. Шекспир","М. Монтень"],"answer":1,"steps":["Гаргантюа и Пантагрюэль у Франсуа Рабле путешествуют и сталкиваются с разными общественными порядками.","Преувеличение помогает автору высмеивать пороки эпохи."]},{"title":"Начало жанра эссе","question":"Основоположником жанра «эссе» считается французский философ-гуманист …","choices":["П. Раме","Ф. Рабле","М. Монтень","Ж. Лефевр"],"answer":2,"steps":["Монтень назвал книгу «Опытами», по-французски Essais.","Он свободно обсуждал в них отдельные вопросы, сопоставляя собственный опыт и прочитанное."]},{"title":"Движение Реформации","question":"Это реформационное движение отстаивало республиканские принципы устройства церкви и общества.","choices":["Цвинглианство","Лютеранство","Англиканство","Гусизм"],"answer":0,"steps":["Ульрих Цвингли проводил преобразования в Цюрихе через городской совет.","Устройство реформированной общины было связано с городским самоуправлением."]},{"title":"Спутник Юпитера","question":"Этот спутник Юпитера был открыт Г. Галилеем в 1610 году.","choices":["Амальтея","Ио","Гималия","Элара"],"answer":1,"steps":["Галилей наблюдал четыре крупных спутника Юпитера — Ио, Европу, Ганимед и Каллисто.","Из них ближе всего к планете обращается Ио."]},{"title":"Границы мироздания","question":"Дж. Бруно характеризовал Вселенную в своей философии как …","choices":["«Стеснённая»","«Бесконечная»","«Сжатая»","«Ограниченная»"],"answer":1,"steps":["Бруно отвергал идею внешней сферы, замыкающей космос.","Он рассуждал о бесконечной Вселенной с множеством звёзд и миров."]},{"title":"Модель из многогранников","question":"Трёхмерная модель Солнечной системы из пяти платоновых тел, созданная И. Кеплером, называется …","choices":["космический кубок","астролябия","армиллярная сфера","галактика"],"answer":0,"steps":["Кеплер вкладывал пять правильных многогранников между сферами, соответствующими орбитам шести известных тогда планет.","В проекте космического кубка расстояния связывались с геометрией этих тел."]},{"title":"Виды опыта","question":"Этот вид опыта, согласно классификации Ф. Бэкона, лучше всего способствует развитию научной практики.","choices":["Социальный","Плодоносный","Медоносный","Вредоносный"],"answer":1,"steps":["Бэкон различал светоносный опыт, позволяющий открыть закономерность, и плодоносный, дающий полезный результат.","Для непосредственной практической пользы подходит второй."]},{"title":"Жанр и остров","question":"Этот автор придумал остров, впоследствии давший название отдельному жанру в литературе.","choices":["Т. Мор","Ф. Рабле","Ф. Бэкон","М. Монтень"],"answer":0,"steps":["Томас Мор описал вымышленный остров и его общественное устройство.","От имени острова возникло название жанра, в котором авторы описывают воображаемое общество."]},{"title":"Бог и природа","question":"Философско-религиозное учение, отождествляющее Бога и природу, характерное для натурфилософии эпохи Возрождения, называется …","choices":["пантеизм","буддизм","космизм","эмпиризм"],"answer":0,"steps":["В пантеизме божественное мыслится как присутствующее во всём мире или совпадающее с природой.","Это отличает его от представления о Боге, полностью отделённом от мира."]},{"title":"Образец для театра","question":"Принципы постройки первых театров эпохи Возрождения были заимствованы у этого античного архитектора.","choices":["Калликрат","Иктин","Рабирий","Витрувий"],"answer":3,"steps":["Витрувий описал устройство римского театра в трактате «Десять книг об архитектуре».","Мастера Возрождения обращались к этой книге, проектируя сцену и места для зрителей."]},{"title":"Власть и страх","question":"Этот философ считал, что правителю лучше быть устрашающим, чем любимым.","choices":["Дж. Бруно","Н. Макиавелли","М. Монтень","Эразм Роттердамский"],"answer":1,"steps":["Макиавелли в «Государе» размышляет о любви и страхе подданных.","Если совместить их нельзя, он советует предпочесть страх, избегая при этом ненависти."]},{"title":"Академия во Флоренции","question":"Идейным лидером Платоновской академии во Флоренции был …","choices":["К. Ландино","Дж. Пико делла Мирандола","М. Фичино","К. Медичи"],"answer":2,"steps":["Марсилио Фичино переводил Платона на латынь.","Вокруг его занятий и покровительства Медичи сформировался круг флорентийских платоников."]},{"title":"Астрономические законы","question":"Этот немецкий учёный в своих книгах сформулировал три закона движения планет, которые названы его именем.","choices":["Н. Кузанский","И. Кеплер","Т. Браге","Эразм Роттердамский"],"answer":1,"steps":["Первый закон Кеплера описывает форму орбиты.","Второй объясняет переменную скорость планеты, а третий связывает размер орбиты со временем обращения."]},{"title":"Мельник и осёл","question":"На высказывание этого философа сослался богатый синьор в сказке Леонардо да Винчи «Мельник и осёл».","choices":["Платон","Аристотель","Пифагор","Диоген"],"answer":2,"steps":["Герой басни иронически обращается к учению о переселении душ, которое связывают с Пифагором.","Эта отсылка и указывает на древнегреческого философа."]},{"title":"Монастырский устав","question":"Согласно басне Леонардо да Винчи, устав запрещает монахам носить при себе …","choices":["деньги","украшения","пропитание","книги"],"answer":0,"steps":["В басне отправной точкой становится запрет иметь при себе деньги.","Он связан с монашеским отказом от личной собственности и определяет поведение персонажа."]},{"title":"Книга для перечитывания","question":"Это знаменитое произведение, по мнению Вольтера, прочитав до конца, хочется перечитать сначала.","choices":["«Неистовый Роланд»","«Освобожденный Иерусалим»","«Божественная комедия»","«Тирант Белый»"],"answer":0,"steps":["Вольтер писал о достоинствах поэмы Ариосто «Неистовый Роланд».","Она переплетает приключения рыцарей, любовные линии и фантастические эпизоды."]},{"title":"Кружок Ронсара","question":"Союз французских поэтов, возглавляемый П. де Ронсаром, назывался …","choices":["«Плодоносное общество»","«Плеяда»","«Атеней искусств»","«Парнас»"],"answer":1,"steps":["Французские поэты XVI века стремились создать национальную литературу, равную античной.","Свой союз из семи поэтов они назвали «Плеядой» по имени звёздного скопления."]},{"title":"Писательница при дворе","question":"Эта представительница королевской семьи была одной из первых французских писательниц эпохи Возрождения.","choices":["Екатерина Медичи","Мария Стюарт","Анна Австрийская","Маргарита Наваррская"],"answer":3,"steps":["Маргарита, сестра Франциска I, стала королевой Наварры.","Она покровительствовала гуманистам и писала стихи, пьесы и новеллы."]},{"title":"Имя на обложке","question":"Две первые книги сатирического романа этого французского литератора вышли под псевдонимом Алькофрибас Назье.","choices":["П. де Ронсар","Ф. Рабле","Ж. дю Белле","М. Монтень"],"answer":1,"steps":["Алькофрибас Назье — анаграмма имени Франсуа Рабле.","Под этим именем он выпустил истории о Пантагрюэле и Гаргантюа."]},{"title":"Возраст великана","question":"Сколько лет прожил Гаргантюа, герой романа Ф. Рабле?","choices":["300 лет","400 лет","500 лет","Более 500 лет"],"answer":3,"steps":["В романе Рабле масштабы жизни великанов преувеличены нарочно.","К моменту смерти Гаргантюа приписывается возраст свыше пяти столетий."]},{"title":"Персонаж Аретино","question":"Пьеса П. Аретино, в которой один из героев носит имя другого итальянского писателя эпохи Возрождения, называется …","choices":["«Кузнец»","«Лицемер»","«Философ»","«Комедия о придворных нравах»"],"answer":2,"steps":["В комедии «Философ» есть герой по имени Боккаччо.","Оно напоминает о Джованни Боккаччо, известном своими новеллами."]},{"title":"Выбор шкатулки","question":"По завещанию отца, героиня комедии У. Шекспира выйдет замуж за того, кто угадает, в каком ящике находится её …","choices":["локон","портрет","перстень","медальон"],"answer":1,"steps":["В «Венецианском купце» женихам Порции предлагают три шкатулки.","Бассаньо выбирает свинцовую и находит в ней портрет Порции."]},{"title":"Герой в двух пьесах","question":"В этой комедии У. Шекспира можно встретить героев его же исторической хроники «Генрих IV».","choices":["«Венецианский купец»","«Двенадцатая ночь, или Что угодно»","«Укрощение строптивой»","«Виндзорские насмешницы»"],"answer":3,"steps":["Шекспир перенёс Фальстафа из пьес о Генрихе IV в комедию о жительницах Виндзора.","В ней его попытка ухаживать сразу за двумя женщинами оборачивается розыгрышами."]},{"title":"Имена в поэзии","question":"Продолжите ряд: Ронсар – Кассандра, Данте – Беатриче, Петрарка – …","choices":["Мария","Елена","Лаура","Патриция"],"answer":2,"steps":["Ронсар посвятил стихи Кассандре, Данте — Беатриче.","Петрарка обращал сонеты к Лауре, поэтому её имя продолжает ряд."]},{"title":"Маски комедии","question":"Кто из персонажей комедии дель арте никогда не надевал маску?","choices":["Влюбленный","Арлекин","Доктор","Панталоне"],"answer":0,"steps":["Слуги, старики и хвастливый Капитан выходили в характерных масках.","Молодые влюблённые обычно выступали с открытыми лицами."]},{"title":"Пьеса и балет","question":"Этот балет создан на основе сюжета пьесы Лопе де Веги.","choices":["«Альцина»","«Мнимый жених»","«Лауренсия»","«Любовью за любовь»"],"answer":2,"steps":["В основе «Лауренсии» лежит «Фуэнте Овехуна» Лопе де Веги.","Героиня поднимает жителей селения против власти командора."]},{"title":"Итальянское Ars nova","question":"Центральной фигурой среди композиторов итальянского Ars nova считается …","choices":["Ф. Ландини","Дж. Палестрина","К. Монтеверди","Дж. Фрескобальди"],"answer":0,"steps":["Франческо Ландини сочинял многоголосные светские баллаты.","Он был органистом и одним из самых известных музыкантов Флоренции XIV века."]},{"title":"Места в коррале","question":"Часть зрительного зала в испанском публичном театре эпохи Возрождения называлась …","choices":["«горшок»","«кружка»","«ложка»","«кастрюля»"],"answer":3,"steps":["В испанских театрах места для женщин часто отводили отдельно.","Ложу для них называли cazuela, то есть «кастрюля»."]},{"title":"Апостолы за столом","question":"В композиции «Тайная вечеря» этот художник изобразил Иуду рядом с другими апостолами по одну сторону стола.","choices":["Тинторетто","Д. Гирландайо","Леонардо да Винчи","А. Дюрер"],"answer":2,"steps":["В росписи трапезной Санта-Мария-делле-Грацие Леонардо поместил Иуду в общую группу учеников.","Его можно узнать по позе, тени на лице и кошельку в руке."],"figure":{"src":"assets/golden-fleece/2015/lessons/7-8/46.webp","alt":"Роспись с группой людей за одним столом","width":560,"height":280,"detailSrc":"assets/golden-fleece/2015/lessons/7-8/46-detail.webp"}},{"title":"Рисунок и геометрия","question":"Этот знаменитый рисунок Леонардо да Винчи называют …","choices":["«человек разумный»","«человек умелый»","«Витрувианский человек»","«человек играющий»"],"answer":2,"steps":["На рисунке одна фигура показана в двух положениях, вписанных в квадрат и окружность.","Леонардо проверял описание человеческих пропорций у римского архитектора Витрувия."],"figure":{"src":"assets/golden-fleece/2015/lessons/7-8/47.webp","alt":"Фигура человека, вписанная в окружность и квадрат","width":412,"height":560,"detailSrc":"assets/golden-fleece/2015/lessons/7-8/47-detail.webp"}},{"title":"Мыслители на фреске","question":"Этот художник изобразил на фреске себя и своих современников в образе великих мыслителей.","choices":["Рафаэль","Мазаччо","Фра Беато Анджелико","Джотто"],"answer":0,"steps":["Рафаэль поместил Платона и Аристотеля в центр «Афинской школы».","Среди фигур он изобразил и собственное лицо, в правой части композиции."],"figure":{"src":"assets/golden-fleece/2015/lessons/7-8/48.webp","alt":"Фреска с группами людей под сводами","width":560,"height":434,"detailSrc":"assets/golden-fleece/2015/lessons/7-8/48-detail.webp"}},{"title":"Портрет возлюбленной","question":"Этот художник Проторенессанса создал для поэта Ф. Петрарки портрет его возлюбленной Лауры.","choices":["С. Мартини","Дж. Пизано","Джотто","А. ди Камбио"],"answer":0,"steps":["Петрарка упоминает в стихах портрет Лауры работы Симоне Мартини.","Сам портрет до нас не дошёл, о нём известно из литературных свидетельств."]},{"title":"Портрет султана","question":"Этот художник был приглашен в Константинополь, где написал портрет турецкого султана Мехмеда II.","choices":["Джованни Беллини","Якопо Беллини","Джентиле Беллини","Витторио Карпаччо"],"answer":2,"steps":["После заключения мира с Османской империей Венеция отправила Джентиле Беллини в Константинополь.","Там он написал Мехмеда II в обрамлении арки."],"figure":{"src":"assets/golden-fleece/2015/lessons/7-8/50.webp","alt":"Мужчина в тюрбане в обрамлении арки","width":128,"height":173}},{"title":"Восточные ворота","question":"Название «Ворота рая» восточным воротам баптистерия Сан-Джованни во Флоренции дал …","choices":["Ф. Брунеллески","Л. Гиберти","Дж. Вазари","Микеланджело"],"answer":3,"steps":["Лоренцо Гиберти украсил двери флорентийского баптистерия рельефами на библейские сюжеты.","По преданию, Микеланджело счёл их достойными быть вратами рая."]},{"title":"Картина в Уффици","question":"Кто написал картину «Мадонна с младенцем и двумя ангелами», которая хранится в галерее Уффици?","choices":["Джотто","Мазаччо","Фра Беато Анджелико","Фра Филиппо Липпи"],"answer":3,"steps":["Галерея Уффици указывает автором Фра Филиппо Липпи. Он написал Марию в профиль и поместил за фигурами пейзаж.","Известно предположение, что для образа Марии могла позировать Лукреция Бути. Имена моделей документально не установлены."],"references":["https://www.uffizi.it/en/artworks/lippi-madonna-and-child-with-two-angels"],"taskUrl":"https://runodog.ru/ZR_1415/ZR_1415_7-8.pdf#page=2","adaptation":"Редакция вопроса проверена по первоисточникам.","figure":{"src":"assets/golden-fleece/2015/lessons/7-8/52.webp","alt":"Женщина и младенец рядом с двумя ангелами","width":128,"height":191}},{"title":"Большая картина","question":"Во Дворце Дожей в Венеции под руководством этого художника была создана картина, площадь которой превышает 150 квадратных метров.","choices":["Микеланджело","Тициан","Тинторетто","П. Веронезе"],"answer":2,"steps":["«Рай» занимает стену зала Большого совета Дворца дожей.","Заказ получил Тинторетто, а над полотном вместе с ним работала мастерская."],"figure":{"src":"assets/golden-fleece/2015/lessons/7-8/53.webp","alt":"Портрет мужчины с тёмной бородой","width":129,"height":161}},{"title":"Посвящение Вазари","question":"Кому посвятил Дж. Вазари труд «Жизнеописания наиболее знаменитых живописцев, ваятелей и зодчих»?","choices":["К. Медичи","Д. Браманте","Леонардо да Винчи","Микеланджело"],"answer":0,"steps":["На титульных страницах издания Вазари указан Козимо I Медичи.","Герцог поддерживал художника и давал ему важные заказы во Флоренции."]},{"title":"Автопортрет","question":"Этот художник на одном из автопортретов изобразил себя в образе, напоминающем Христа.","choices":["П. Брейгель Ст.","Г. Гольбейн Мл.","Я. ван Эйк","А. Дюрер"],"answer":3,"steps":["Дюрер изобразил себя лицом к зрителю, с длинными волосами и поднятой рукой.","Такая фронтальная композиция напоминает изображения Христа того времени."],"figure":{"src":"assets/golden-fleece/2015/lessons/7-8/55.webp","alt":"Фронтальный портрет мужчины с длинными волосами","width":131,"height":181}},{"title":"Смысл образа","question":"Воз сена на одноименном триптихе И. Босха считается аллегорией …","choices":["зависти","лицемерия","жажды земных благ","тщеславия"],"answer":2,"steps":["В центральной сцене Босха толпа старается урвать сено с воза.","Сено становится образом земных выгод, за которыми гонятся люди разных сословий."],"figures":[{"src":"assets/golden-fleece/2015/lessons/3-4/59-1.webp","alt":"Левая створка триптиха","caption":"Левая створка","width":187,"height":560,"detailSrc":"assets/golden-fleece/2015/lessons/3-4/59-1-detail.webp"},{"src":"assets/golden-fleece/2015/lessons/3-4/59-2.webp","alt":"Центральная часть триптиха","caption":"Центральная часть","width":412,"height":560,"detailSrc":"assets/golden-fleece/2015/lessons/3-4/59-2-detail.webp"},{"src":"assets/golden-fleece/2015/lessons/3-4/59-3.webp","alt":"Правая створка триптиха","caption":"Правая створка","width":186,"height":560,"detailSrc":"assets/golden-fleece/2015/lessons/3-4/59-3-detail.webp"}]},{"title":"Имя зонда","question":"Именем этого художника назван космический аппарат.","choices":["Чимабуэ","Джотто","С. Мартини","Дж. Пизано"],"answer":1,"steps":["На фреске «Поклонение волхвов» Джотто показал звезду с хвостом, похожим на хвост кометы.","В его честь назвали зонд, исследовавший комету Галлея."]},{"title":"Фреска на потолке","question":"Автор этой фрески реализовал в ней эффект архитектурной иллюзии.","choices":["Рафаэль","Тициан","А. Мантенья","П. Веронезе"],"answer":2,"steps":["Мантенья написал на потолке Камеры дельи Спози круглый проём с балюстрадой.","Ракурс фигур и вид открытого неба создают ощущение настоящего отверстия."],"figure":{"src":"assets/golden-fleece/2015/lessons/7-8/58.webp","alt":"Роспись с круглым проёмом и фигурами на балюстраде","width":172,"height":174}},{"title":"Цвет неба","question":"Этот художник в одном из своих трактатов описал причину синевы неба.","choices":["Леонардо да Винчи","А. Дюрер","С. Боттичелли","Рафаэль"],"answer":0,"steps":["Леонардо рассуждал о прохождении солнечного света через воздух и мелкие частицы.","Он пытался найти физическое объяснение тому, как возникает видимый голубой цвет."]},{"title":"Символ города","question":"В этом творении Микеланджело воплощена патриотическая идея флорентинцев.","choices":["«Давид»","«Пьета»","«Вакх»","«Моисей»"],"answer":0,"steps":["Микеланджело показал Давида перед схваткой с Голиафом.","Флорентийцы поставили статую у дворца правительства и видели в ней образ защиты республики."],"figure":{"src":"assets/golden-fleece/2015/lessons/7-8/60.webp","alt":"Мраморная статуя юноши","width":128,"height":247}}]);
edition.sources.readers = {"tasksUrl":"assets/golden-fleece/2015/ZR_1415_7-8-reading.pdf"};
register(edition, globalThis.KENGURU_CHOICE_LAYOUTS, {});
